import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { toast } from 'react-toastify';
import { useAuth } from '../../context/AuthContext';
import './Auth.css';

const Signup = () => {
    const navigate = useNavigate();
    const { register } = useAuth();

    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [role, setRole] = useState('student');
    const [loading, setLoading] = useState(false);

    // Dynamic course list
    const [courseList] = useState(() => {
        const defaults = [
            "B.Sc Information Technology",
            "Bachelors of Marketing",
            "Bachelors of Finance Management",
            "Bachelors for Commerce",
            "Bachelors of Banking & Insurance",
            "BAMMC"
        ];
        const saved = localStorage.getItem('customCourses');
        const custom = saved ? JSON.parse(saved) : [];
        const customTitles = custom.map(c => c.title);
        return [...defaults, ...customTitles];
    });

    const [course, setCourse] = useState(localStorage.getItem('selectedCourse') || (courseList[0] || ''));
    const [teacherCourses, setTeacherCourses] = useState(() => {
        const saved = localStorage.getItem('selectedTeacherCourses');
        return saved ? JSON.parse(saved) : [];
    });

    const handleCourseCheckbox = (e, c) => {
        if (e.target.checked) {
            setTeacherCourses(prev => [...prev, c]);
        } else {
            setTeacherCourses(prev => prev.filter(item => item !== c));
        }
    };

    const validateEmail = (email) => {
        const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return re.test(String(email).toLowerCase());
    };

    const handleSignup = async (e) => {
        e.preventDefault();

        if (!validateEmail(email)) {
            toast.error("Please enter a valid email address.");
            return;
        }

        if (password.length < 6) {
            toast.error("Password must be at least 6 characters long.");
            return;
        }

        setLoading(true);

        try {
            console.log(`📝 Creating ${role} account for ${email}...`);

            const userData = {
                name,
                email,
                password,
                role
            };

            if (role === 'teacher') {
                if (teacherCourses.length === 0) {
                    toast.error("Please select at least one course.");
                    setLoading(false);
                    return;
                }
                userData.course = teacherCourses;
                localStorage.setItem('selectedTeacherCourses', JSON.stringify(teacherCourses));
            } else {
                userData.course = course;
                localStorage.setItem('selectedCourse', course);
            }

            const result = await register(userData);
            console.log('✅ Account created successfully:', result);

            const message = role === 'student' 
                ? "Account created! You will need teacher approval to access courses. Please login to proceed." 
                : "Account created! Please login to start teaching.";

            toast.success(message);
            console.log(`📍 Redirecting to login page to authenticate...`);
            navigate('/login', { state: { role } });
        } catch (error) {
            console.error('Signup error:', error);
            const errorMessage = error?.message || 'Signup failed. Please try again.';
            toast.error(errorMessage);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="auth-container">
            <div className="card auth-box">
                <h1 className="mb-20 auth-title">Create Account</h1>

                <form onSubmit={handleSignup}>
                    {/* Role Selection */}
                    <div className="form-group">
                        <label className="auth-label">I am a...</label>
                        <select
                            value={role}
                            onChange={(e) => setRole(e.target.value)}
                            className="auth-input"
                        >
                            <option value="student">Student</option>
                            <option value="teacher">Teacher</option>
                        </select>
                    </div>

                    {/* Course Selection */}
                    {role === 'student' ? (
                        <div className="form-group animate-fade-in">
                            <label className="auth-label">Select Your Course</label>
                            <select
                                value={course}
                                onChange={(e) => setCourse(e.target.value)}
                                className="auth-input animated-focus"
                                required
                            >
                                {courseList.map((c, index) => (
                                    <option key={index} value={c}>{c}</option>
                                ))}
                            </select>
                        </div>
                    ) : (
                        <div className="form-group animate-fade-in">
                            <label className="auth-label">Select Your Courses</label>
                            <div className="checkbox-group" style={{ 
                                maxHeight: '150px', 
                                overflowY: 'auto',
                                padding: '10px',
                                border: '1px solid #ccc',
                                borderRadius: '4px',
                                backgroundColor: '#fff',
                                width: '100%',
                                boxSizing: 'border-box'
                            }}>
                                {courseList.map((c, index) => (
                                    <label key={index} style={{ display: 'block', marginBottom: '10px', cursor: 'pointer', textAlign: 'left', fontSize: '1rem' }}>
                                        <input
                                            type="checkbox"
                                            value={c}
                                            checked={teacherCourses.includes(c)}
                                            onChange={(e) => handleCourseCheckbox(e, c)}
                                            style={{ cursor: 'pointer', marginRight: '10px', verticalAlign: 'middle', width: '16px', height: '16px' }}
                                        />
                                        <span style={{ color: '#333', verticalAlign: 'middle' }}>{c}</span>
                                    </label>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Name Input */}
                    <div className="form-group">
                        <label className="auth-label">Name</label>
                        <input
                            type="text"
                            placeholder="Enter your full name"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            required
                            className="auth-input"
                        />
                    </div>

                    {/* Email Input */}
                    <div className="form-group">
                        <label className="auth-label">Email Address</label>
                        <input
                            type="email"
                            placeholder="Enter your email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required
                            className="auth-input"
                        />
                    </div>

                    {/* Password Input */}
                    <div className="form-group-last">
                        <label className="auth-label">Password</label>
                        <input
                            type="password"
                            placeholder="Create a password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required
                            className="auth-input"
                        />
                    </div>

                    {/* Signup Button */}
                    <button 
                        type="submit" 
                        className="btn btn-primary auth-button"
                        disabled={loading}
                    >
                        {loading ? 'Creating Account...' : 'Sign Up'}
                    </button>
                </form>

                <div className="auth-footer">
                    <p className="auth-text">Already have an account? <Link to="/login" className="auth-link">Login here</Link></p>
                </div>
            </div>
        </div>
    );
};

export default Signup;
